args.new:
/**
 * Summarize a list of cart line items into a count of line items and the
 * total price. Each call returns a fresh, independent summary object.
 * @param {LineItem[]} items
 * @returns {{ count: number, total: number }}
 */
export function summarize(items) {
  return items.reduce(
    (acc, item) => {
      acc.count += 1;
      acc.total += item.price * item.qty;
      return acc;
    },
    { count: 0, total: 0 },
  );
}

args.old:
/** Shared zero-value accumulator reused across calls. */
const ZERO = { count: 0, total: 0 };

/**
 * Summarize a list of cart line items into a count of line items and the
 * total price.
 * @param {LineItem[]} items
 * @returns {{ count: number, total: number }}
 */
export function summarize(items) {
  return items.reduce((acc, item) => {
    acc.count += 1;
    acc.total += item.price * item.qty;
    return acc;
  }, ZERO);
}

args.command:
python -c "open(r'leaderboard.mjs','w').write('''/**
 * Ranks players by points (descending), breaking ties by name (ascending).
 *
 * @param {{ name: string, points: number }[]} players - Array of player objects.
 * @returns {string[]} Array of "name:points" strings in ranked order.
 */
export function rank_players(players) {
  return [...players]
    .sort((a, b) => {
      if (b.points !== a.points) {
        return b.points - a.points;
      }
      if (a.name < b.name) return -1;
      if (a.name > b.name) return 1;
      return 0;
    })
    .map((player) => `${player.name}:${player.points}`);
}
''')" && node --test check.mjs

python -c "p='csvlite.py'; s=open(p, encoding='utf-8').read(); a=s.index('    rows = []'); b=s.index('    return rows')+15; t='''    rows = []
    row = []
    field = []
    field_started = False
    in_quotes = False
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if in_quotes:
            if ch == 'QQ':
                if i + 1 < n and text[i + 1] == 'QQ':
                    field.append('QQ')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                field.append(ch)
                i += 1
            continue
        if ch == ',':
            row.append(''.join(field))
            field = []
            field_started = True
            i += 1
        elif ch == '\n' or ch == '\r':
            if ch == '\r' and i + 1 < n and text[i + 1] == '\n':
                i += 2
            else:
                i += 1
            if field or field_started:
                row.append(''.join(field))
            rows.append(row)
            row = []
            field = []
            field_started = False
        else:
            if ch == 'QQ' and not field:
                in_quotes = True
            else:
                field.append(ch)
            field_started = True
            i += 1
    if in_quotes or field or field_started:
        row.append(''.join(field))
        rows.append(row)
    return rows'''; open(p, 'w', encoding='utf-8', newline='').write(s[:a] + t.replace('QQ', chr(34)) + s[b:])" && type csvlite.py

